function readEnv(){const o={}; for(const l of fs.readFileSync(path.join(SERVER,'.env'),'utf8').split(/\r?\n/)){const m=l.match(/^([^#=]+)=(.*)$/); if(m)o[m[1].trim()]=m[2].trim();} return o;}
function add(group,id,name,ok,detail={},err){const item={id,name,status:ok?'PASS':'FAIL',detail,at:new Date().toISOString()}; if(err)item.error=String(err.message||err); ev[group].push(item); console.log(`${ok?'✅':'❌'} ${group.toUpperCase()} ${id} ${name}${err?' :: '+item.error:''}`); if(!ok)ev.defects.push(item); return ok;}
function pass(g,id,n,d){return add(g,id,n,true,d)}; function fail(g,id,n,d,e){return add(g,id,n,false,d,e||new Error('断言失败'))}
function assert(g,id,n,c,d){return c?pass(g,id,n,d):fail(g,id,n,d)}
async function api(p,opt={}){const h={'content-type':'application/json',...(opt.headers||{})}; if(global.token)h.authorization='Bearer '+global.token; const r=await fetch(API+p,{...opt,headers:h}); const t=await r.text(); let j; try{j=t?JSON.parse(t):null}catch{j=t} if(!r.ok || (j&&j.code>=400)){const e=new Error(j?.message||t||`HTTP ${r.status}`); e.status=r.status; e.body=j; throw e} return j&&Object.prototype.hasOwnProperty.call(j,'data')?j.data:j}
async function db(pool,q,inputs={}){const req=pool.request(); for(const [k,v] of Object.entries(inputs))req.input(k,v); return (await req.query(q)).recordset}
async function one(pool,q,inputs={}){return (await db(pool,q,inputs))[0]}
async function insert(pool,table,obj){const cols=Object.keys(obj); const req=pool.request(); cols.forEach(c=>req.input(c,obj[c])); return (await req.query(`insert into ${table} (${cols.map(c=>'['+c+']').join(',')}) output inserted.id values (${cols.map(c=>'@'+c).join(',')})`)).recordset[0].id}
async function prepare(pool){const suffix=RUN.replace(/\D/g,'').slice(-10); const now=new Date(); const common={created_at:now,updated_at:now,is_deleted:0}; const password=`P1_${suffix}_Pwd`; const userId=await insert(pool,'sys_user',{username:`p1acc_${suffix}`,password:bcrypt.hashSync(password,10),real_name:'P1验收',email:'',phone:'',dept_id:null,emp_id:null,avatar:'',status:1,...common}); const supplierId=await insert(pool,'master_supplier',{supplier_code:`P1SUP_${suffix}`,supplier_name:`P1供应商_${suffix}`,short_name:`P1SUP_${suffix}`,supplier_type:1,contact_person:'P1',contact_phone:'',email:'',address:'',payment_term_id:null,buyer_id:null,tax_number:'',bank_name:'',bank_account:'',status:1,remark:RUN,...common}); const warehouseId=await insert(pool,'master_warehouse',{warehouse_code:`P1WH_${suffix}`,warehouse_name:`P1仓_${suffix}`,warehouse_type:1,parent_id:null,manager_id:null,address:'',is_default:0,status:1,remark:RUN,...common}); const unitId=await insert(pool,'master_unit',{unit_code:`P1U_${suffix}`,unit_name:'个',unit_type:1,precision:4,status:1,remark:RUN,...common}); const materialId=await insert(pool,'master_material',{material_code:`P1MAT_${suffix}`,material_name:`P1物料_${suffix}`,material_spec:'P1-SPEC',category_id:null,unit_id:unitId,material_type:2,purchase_type:1,barcode:'',default_warehouse:warehouseId,safety_stock:0,min_order_qty:0,lead_time:0,standard_cost:0,sale_price:0,is_batch_manage:0,is_serial_manage:0,shelf_life_days:0,status:1,remark:RUN,...common}); const currencyId=await insert(pool,'master_currency',{currency_code:`C${suffix.slice(-5)}`,currency_name:`P1币_${suffix}`,currency_symbol:'¥',exchange_rate:1,is_base:0,status:1,remark:RUN,...common}); const paymentTermId=await insert(pool,'master_payment_term',{term_code:`P1PT_${suffix}`,term_name:`P1月结_${suffix}`,term_type:3,credit_days:30,advance_ratio:0,stage1_ratio:0,stage2_ratio:0,stage3_ratio:0,status:1,remark:RUN,...common}); const orgId=randomUUID(); const login=await api('/auth/login',{method:'POST',body:JSON.stringify({username:`p1acc_${suffix}`,password})}); global.token=login.accessToken; const ctx={suffix,userId,supplierId,warehouseId,unitId,materialId,currencyId,paymentTermId,orgId}; ev.ids=ctx; return ctx}
