 if(needCheck){ const qi=await api('/quality-inspections/incoming/from-receive-entry',{method:'POST',body:JSON.stringify({receiveNoticeEntryId:rna.entries[0].id})}); await api(`/quality-inspections/${qi.id}`,{method:'PUT',body:JSON.stringify({inspectionQty:qty,qualifiedQty:qty,unqualifiedQty:0,concessionQty:0,inspectionDate:'2026-07-20',inspector:'P1'})}); await api(`/quality-inspections/${qi.id}/submit`,{method:'POST'}); await api(`/quality-inspections/${qi.id}/approve`,{method:'POST',body:JSON.stringify({approvedBy:'P1'})}); rna=await api(`/purchase-receive-notices/${rn.id}`); }
